Schema:
{
  "$schema": "http://json-schema.org/draft-04/schema#",
  "description": "A vaccine delivery driver",
  "properties": {
    "doc_type": {
      "pattern": "^driver$",
      "type": "string"
    },
    "email": {
      "_format": "email",
      "chance": "email",
      "type": "string"
    },
    "forename": {
      "faker": "name.firstName",
      "minLength": 1,
      "type": "string"
    },
    "phone": {
      "faker": "phone.phoneNumber",
      "type": "string"
    },
    "surname": {
      "faker": "name.lastName",
      "minLength": 1,
      "type": "string"
    },
    "version": {
      "_format": "semver",
      "type": "string"
    }
  },
  "required": [
    "doc_type",
    "version",
    "forename",
    "surname",
    "email",
    "phone"
  ],
  "title": "Driver",
  "type": "object"
}

Generează un obiect JSON valid care respectă schema de mai jos. Explică întâi pe scurt, în limba română, ce reprezintă obiectul și ce câmpuri conține, apoi scrie blocul JSON la finalul răspunsului.

