          "type": "string"
        },
        "number": {
          "description": "The credit card number, preferably numbers only.",
          "maxLength": 20,
          "minLength": 10,
          "type": "string"
        },
        "security_code": {
          "description": "The 3 or 4-digit card security code (CVV2, CVC2, or CID).",
