          "type": "string"
        }
      },
      "required": [
        "number",
        "expiration",
        "security_code",
        "billing_address"
      ],
      "type": "object"
    },
    "customer": {
      "description": "The platform's customer.",
      "maxLength": 96,
      "minLength": 1,
      "type": "string"
    }
  },
  "required": [
    "customer",
    "account_identifier",
    "client_ip",
    "credit_card"
  ],
  "title": "Register a card to a platform user's account.",
  "type": "object"
